"""Resolve exact method versions, classify all candidates and validate bindings.

The caller supplies owner-visible, admitted records from the repository. This
compiler proves structural consistency, not incubation approval or use rights.
"""

from dataclasses import dataclass
from typing import Literal
from uuid import UUID

from jsonschema import Draft202012Validator
from jsonschema.exceptions import ValidationError

from app.domain.workbench.formal_method_generated import (
    FormalMethodDefinition,
    LiteralValue,
    MethodRef,
    Orchestration,
    ToolProcedure,
)

Kind = Literal["tool", "expert", "expert_team"]


def classify_dependencies(
    implementation: Literal["direct", "orchestration"],
    dependencies: tuple[tuple[UUID, Kind], ...],
) -> Kind:
    """Types are resolved from admitted records, never remote tool annotations."""
    if implementation == "direct":
        if dependencies:
            raise ValueError("A tool method cannot call another method")
        return "tool"
    if not dependencies:
        raise ValueError("An orchestrated method must call at least one method")
    if any(kind == "expert_team" for _, kind in dependencies):
        return "expert_team"
    experts = {mid for mid, kind in dependencies if kind == "expert"}
    return "expert_team" if len(experts) >= 2 else "expert"


@dataclass(frozen=True)
class FrozenMethod:
    reference: MethodRef
