def compile_method(
    method_id: UUID,
    definition: FormalMethodDefinition,
    resolved: dict[tuple[UUID, int], FrozenMethod],
    *,
    max_depth: int = 16,
    max_expansions: int = 1000,
) -> MethodCompilation:
    count = 0

    def visit(
        mid: UUID, current: FormalMethodDefinition, path: tuple[UUID, ...]
    ) -> Kind:
        nonlocal count
        count += 1
        if mid in path or len(path) >= max_depth or count > max_expansions:
            raise ValueError("Method dependency cycle or expansion limit")
        if isinstance(current.procedure, ToolProcedure):
            return "tool"
        dependency_kinds = []
        for step in current.procedure.steps:
            for ref in step.candidates:
                child = resolved.get((ref.method_id, ref.version))
                if (
                    child is None
                    or child.reference != ref
                    or child.definition.digest() != ref.digest
                ):
                    raise ValueError("Missing or changed frozen method dependency")
                child_kind = visit(ref.method_id, child.definition, (*path, mid))
                dependency_kinds.append((ref.method_id, child_kind))
                _step_interface(step, child.definition.interfaces())
                _permission_ceiling(current, child.definition)
        return classify_dependencies("orchestration", tuple(dependency_kinds))

    kind = visit(method_id, definition, ())
    refs = {}
    if isinstance(definition.procedure, Orchestration):
        for step in definition.procedure.steps:
            for ref in step.candidates:
                key = (ref.method_id, ref.version)
                if key in refs and refs[key] != ref:
                    raise ValueError("One method version cannot have two digests")
                refs[key] = ref
    return MethodCompilation(
        method_kind=kind,
        dispatch="direct" if kind == "tool" else "orchestration",
        definition_digest=definition.digest(),
        dependencies=tuple(refs.values()),
        interfaces=definition.interfaces(),
    )


def _step_interface(step, interface):
    inputs, outputs = interface["inputs"], interface["outputs"]
    required = {key for key, value in inputs.items() if value["required_by"]}
    if not required <= step.inputs.keys() or not step.inputs.keys() <= inputs.keys():
        raise ValueError("Step bindings do not match the candidate input interface")
    for name, item in step.inputs.items():
        target = inputs[name]["slot"]
        if (
            item.slot.schema_ != target["schema"]
            or item.slot.meaning != target["meaning"]
        ):
            raise ValueError(
                "Step input shape or business meaning differs from the method"
            )
        if name in required and not item.slot.required:
            raise ValueError("Step cannot weaken a required method input")
        if isinstance(item.binding, LiteralValue):
            try:
                Draft202012Validator(target["schema"]).validate(item.binding.value)
            except ValidationError as exc:
                raise ValueError(
                    "Fixed input does not match its method schema"
                ) from exc
    for name, slot in step.outputs.items():
        provided = outputs.get(name)
        if (
            provided is None
            or slot.schema_ != provided["slot"]["schema"]
            or slot.meaning != provided["slot"]["meaning"]
        ):
            raise ValueError("Step output must be an unchanged candidate output")
        if slot.required and not provided["always_present"]:
            raise ValueError(
                "A conditional candidate output cannot be promised unconditionally"
            )


def _permission_ceiling(parent, child):
    """Declarations are ceilings, not grants; runtime still narrows live authority."""
    for need in child.access_requirements:

        def covers(ceiling, need=need):
            resources = {
                (r.resource_kind, r.resource_role): set(r.values)
                for r in ceiling.resources
            }
            wanted = {
                (r.resource_kind, r.resource_role): set(r.values)
                for r in need.resources
            }
            return (
                ceiling.capability_ref == need.capability_ref
                and ceiling.version == need.version
                and set(need.operations) <= set(ceiling.operations)
                and ceiling.data_transfer.destination == need.data_transfer.destination
                and ceiling.data_transfer.purpose == need.data_transfer.purpose
                and set(need.data_transfer.argument_fields)
                <= set(ceiling.data_transfer.argument_fields)
                and resources.keys() == wanted.keys()
                and all(values <= resources[role] for role, values in wanted.items())
            )

        if not any(covers(ceiling) for ceiling in parent.access_requirements):
            raise ValueError("A candidate's permissions exceed the parent declaration")
